import { Component, createSignal, onMount, ParentComponent, Show } from "solid-js";

import { ActivatableAudio } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Flipbook } from "#core/ui-next/components/flipbook.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { HeroButton2 } from "#core/ui-next/components/hero-button.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-compat.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { getCivLoadingInfo } from "#base/ui-next/screens/load-screen/load-screen-model.js";
import { LoadScreenProps, useLoadScreenContext } from "#base/ui-next/screens/load-screen/load-screen.jsx";

import style from "./age-transition-load-screen.scss?url";

export interface AgeTransitionStageProps {
	background: string;
	icon: string;
}

const AgeTransitionStageComponent: ParentComponent<AgeTransitionStageProps> = (props) => {
	return (
		<div class="age-transition-stage-bg img-unit-panelbox relative flex-auto">
			<div
				class="absolute inset-1 bg-center bg-cover bg-no-repeat"
				style={{ "background-image": `url('blp:${props.background}')` }}
			/>
			<div
				class="absolute inset-1 bg-center bg-cover bg-no-repeat"
				style={{ background: "rgba(7, 7, 7, 0.30)" }}
			/>
			<div
				class="absolute inset-1 bg-center bg-cover bg-no-repeat"
				style={{ "background-image": `url('blp:create_game_gradient1')` }}
			/>
			<div class="absolute -top-5 left-0 right-0 flex items-center justify-center">
				<div class="filigree-divider-h2 -scale-y-100" />
			</div>

			<div class="absolute -bottom-5 left-0 right-0 flex items-center justify-center">
				<div class="filigree-divider-h2" />
			</div>

			<div class="absolute inset-1 flex flex-row relative justify-start">
				<div class=" w-1\/4 flex flex-col items-center justify-center">
					<Icon
						class="size-62"
						name={`url('${props.icon ?? ""}')`}
						isUrl={true}
					/>
				</div>

				<div class="w-1\/2 flex flex-col items-center justify-center">{props.children}</div>
			</div>
		</div>
	);
};

export const AgeTransitionStage = ComponentRegistry.register({
	name: "AgeTransitionStage",
	createInstance: AgeTransitionStageComponent,
});

const AgeTransitionLoadScreenComponent: Component<LoadScreenProps> = (props) => {
	// TODO: Move all this to a model
	const model = useLoadScreenContext();

	// TODO: Put these in a database somewhere
	function getAgeHeader(age: string) {
		return `LOC_LOADING_AGE_TRANSITION_${age.replace("AGE_", "")}_HEADER`;
	}

	function getAgeText(age: string) {
		return `LOC_LOADING_AGE_TRANSITION_${age.replace("AGE_", "")}`;
	}

	function getAgeBannerName(age: string) {
		return `LOC_LOADING_AGE_START_${age.replace("AGE_", "")}`;
	}

	function ageBg(ageType: string) {
		return `${ageType.toLowerCase().replace("age_", "shell_")}-select`;
	}

	const curAge = GameInfo.Ages.lookup(Configuration.getGame().startAgeType);
	const ageName = curAge?.AgeType ?? "";

	const ageHeader = getAgeHeader(ageName);
	const ageText = getAgeText(ageName);
	const ageBannerName = getAgeBannerName(ageName);
	const curAgeBg = ageBg(ageName);

	const curCivLoadInfo = getCivLoadingInfo();
	const curCivIcon = UI.getIconURL(curCivLoadInfo?.CivilizationType ?? "");

	const [activeTab, setActiveTab] = createSignal("age-start");
	const [hasStartButton, setHasStartButton] = createSignal(true);

	onMount(() => {
		setTimeout(() => {
			setActiveTab("age-quote");
		}, 5000);
	});

	function startGame() {
		setHasStartButton(false);
		model.onBeginGame();
	}

	return (
		<NestedTooltipContext.Provider value={{ disabled: true }}>
			<Panel
				name="age-transition-load-screen"
				class="fullscreen load-screen-fade-in flex flex-col justify-center"
				id="age-transition-load-screen"
				style={{ opacity: 0 }}
				ref={props.ref}
			>
				<div class="age-transition-load-screen-bg absolute inset-0" />

				<Tab activeTab={activeTab}>
					<Tab.Output />
					<Tab.Item
						name="age-quote"
						title={() => null}
						body={() => (
							<AgeTransitionStageComponent
								background={curCivLoadInfo?.BackgroundImageHigh ?? "antiquity_domination_victory"}
								icon={curCivIcon}
							>
								<div class="flex flex-col items-start justify-center m-4 gap-4">
									<Header class="uppercase text-xl">
										<L10n.Compose text={ageHeader} />
									</Header>
									<L10n.Stylize
										class="text-lg"
										text={ageText}
									/>
								</div>
							</AgeTransitionStageComponent>
						)}
					/>
					<Tab.Item
						name="age-start"
						title={() => null}
						body={() => (
							<AgeTransitionStageComponent
								background={curAgeBg}
								icon={curCivIcon}
							>
								<Header class="uppercase flex flex-col items-center justify-center">
									<L10n.Stylize
										class="age-transition-banner-text-sm text-center"
										text="LOC_LOADING_AGE_START_PREFIX"
									/>
									<L10n.Stylize
										class="age-transition-banner-text-lg text-center"
										text={ageBannerName}
									/>
									<L10n.Stylize
										class="age-transition-banner-text-sm text-center"
										text="LOC_LOADING_AGE_START_SUFFIX"
									/>
								</Header>
							</AgeTransitionStageComponent>
						)}
					/>
				</Tab>
				<div class="flex flex-row items-center justify-center">
					<AudioContextProvider
						segment="LoadScreen"
						vars={{ canBeginGame: model.canBeginGame.toString() }}
					>
						<HeroButton2
							class="mx-3 px-8 mt-10"
							style={{ visibility: hasStartButton() ? undefined : "hidden" }}
							disabled={!model.canBeginGame}
							onActivate={() => startGame()}
							classList={{ hidden: model.hideBeginButton }}
						>
							<NavHelp
								class="-ml-10 mr-2"
								disabled={!model.canBeginGame}
							/>
							<L10n.Compose text="LOC_GENERIC_CONTINUE" />
						</HeroButton2>
					</AudioContextProvider>
				</div>

				<Show when={!model.canBeginGame}>
					<Flipbook.Hourglass class="absolute top-10 right-10 size-32" />
				</Show>
			</Panel>
		</NestedTooltipContext.Provider>
	);
};

export const AgeTransitionLoadScreen = ComponentRegistry.register({
	name: "AgeTransitionLoadScreen",
	createInstance: AgeTransitionLoadScreenComponent,
	styles: [style],
});
